passages:
{'record_date': [{'quote': 'Under the terms of the rights offering, the Company will grant, at no charge, to each stockholder as of the close of business on the record date of February 2, 2026, one non-transferable subscription right for each whole share of common stock owned by that stockholder on the record date.', 'location': 'emp_8k-19025.htm, Item 8.01 Other Events'}], 'subscription_ratio': [{'quote': 'Under the terms of the rights offering, the Company will grant, at no charge, to each stockholder as of the close of business on the record date of February 2, 2026, one non-transferable subscription right for each whole share of common stock owned by that stockholder on the record date. Each subscription right will entitle a rights holder to purchase 0.057 shares of the Company’s common stock at a subscription price equal to $2.99 per whole share (subject to rounding down to avoid the issuance of fractional shares).', 'location': 'emp_8k-19025.htm, Item 8.01 Other Events'}, {'quote': 'The number of Subscription Rights to be issued to Record Date Stockholders will be rounded down to the nearest whole number and fractional shares of Common Stock will not be issued upon the exercise of the Subscription Rights.', 'location': 'exh_99-2.htm, Form of Letter to Stockholders who are Record Holders'}], 'subscription_price': [{'quote': 'Record Date Stockholders will be required to pay for Common Stock pursuant to your Subscription Rights at the subscription price of $2.99 per share of Common Stock (the “Subscription Price”).', 'location': 'exh_99-2.htm, Form of Letter to Stockholders who are Record Holders'}], 'expiration_date': [{'quote': 'The Subscription Rights will expire if they are not exercised by 5:00 p.m., Eastern Time, on February 27, 2026, unless the Company extends the Rights Offering period as described in the Prospectus (such date and time, as it may be extended, the “Expiration Date”).', 'location': 'exh_99-2.htm, Form of Letter to Stockholders who are Record Holders'}, {'quote': 'The Rights Offering is expected to expire at 5:00 p.m., Eastern Time, on February 27, 2026 (“Expiration Date”), subject to extension or earlier termination.', 'location': 'exh_99-6.htm, Press Release Dated February 2, 2026'}], 'oversubscription_rights': [{'quote': 'Record Date Stockholders who fully exercise all Subscription Rights initially issued to them are entitled to an Over-Subscription Right to buy those shares of Common Stock (“Over-Subscription Shares”) that remain unsubscribed at the Expiration Date at the same Subscription Price. If enough Over-Subscription Shares are available, all such requests will be honored in full. If the requests for Over-Subscription Shares exceed the Over-Subscription Shares available, the available Over-Subscription Shares will be allocated pro rata among the Record Date Stockholders who have fully exercised their Subscription Rights and who have requested to over-subscribe, based on the number of shares of Common Stock purchased by virtue of their Subscription Rights.', 'location': 'exh_99-2.htm, Form of Letter to Stockholders who are Record Holders'}, {'quote': 'Any excess payments made by Record Date Stockholders as a result of the exercise of their Over-Subscription Rights (if any) will be refunded and will be mailed by Securities Transfer Corporation to such holder as soon as practicable after the Expiration Date.', 'location': 'exh_99-2.htm, Form of Letter to Stockholders who are Record Holders'}], 'rights_transferable': [{'quote': 'THESE SUBSCRIPTION RIGHTS ARE NON-TRANSFERABLE.', 'location': 'exh_99-1.htm, Form of Rights Certificate'}], 'event_status': [{'quote': 'Empire Petroleum Corporation (NYSE American: EP) ("Empire" or the "Company"), an oil and gas company with current producing assets in New Mexico, North Dakota, Montana, Texas, and Louisiana, announced today that it has commenced its previously announced subscription rights offering (“Rights Offering”) pursuant to which it intends to raise gross proceeds of up to approximately $6.0 million.', 'location': 'exh_99-6.htm, Press Release Dated February 2, 2026'}], 'security_description': [{'quote': 'In the Rights Offering, the Company is offering an aggregate of 2,006,689 shares of Common Stock to be issued upon the exercise of the Subscription Rights and Over-Subscription Rights (as defined below), which are described further in the Prospectus.', 'location': 'exh_99-2.htm, Form of Letter to Stockholders who are Record Holders'}, {'quote': 'This notice is being distributed by Empire Petroleum Corporation (the “Company”) to all holders of record of shares of its common stock, par value $0.001 per share ( “Common Stock”), at the close of business on February 2, 2026 (the “Record Date”), in connection with an offering (the “Rights Offering”) of non-transferable subscription rights (the “Subscription Rights”) to subscribe for and purchase shares of Common Stock.', 'location': 'exh_99-2.htm, Form of Letter to Stockholders who are Record Holders'}], 'effective_date': [], 'available_options': [{'quote': '1.	You
can subscribe for all of the shares underlying the number of rights listed at the top of this page;
2.	You
can subscribe for less than all of the shares underlying the number of rights listed above, and allow the rest of your subscription
rights to expire;
3.	If
you have subscribed for all of such shares (exercised your subscription right in full), then you can also subscribe for additional
shares of common stock, subject to an allocation process as described in the Prospectus; or
4.	If
you do not want to purchase any shares, you can disregard this material.', 'location': 'exh_99-1.htm, Form of Rights Certificate'}, {'quote': 'Each subscription right will entitle the holder to purchase 0.057 shares of our common stock at the subscription price of $2.99 per share (the “Subscription Price”).', 'location': 'exh_99-1.htm, Form of Rights Certificate'}, {'quote': 'To subscribe for any number of shares, full payment of the Subscription Price is required for each share of common stock you are subscribing for (including under the over-subscription right). You must complete the reverse side of this form to subscribe for new shares.', 'location': 'exh_99-1.htm, Form of Rights Certificate'}, {'quote': 'If the requests for Over-Subscription Shares exceed the Over-Subscription Shares available, the available Over-Subscription Shares will be allocated pro rata among the Record Date Stockholders who have fully exercised their Subscription Rights and who have requested to over-subscribe, based on the number of shares of Common Stock purchased by virtue of their Subscription Rights.', 'location': 'exh_99-2.htm, Form of Letter to Stockholders who are Record Holders'}, {'quote': 'A Rights holder cannot revoke the exercise of its Rights.', 'location': 'exh_99-2.htm, Form of Letter to Stockholders who are Record Holders'}, {'quote': 'THESE SUBSCRIPTION RIGHTS ARE NON-TRANSFERABLE.', 'location': 'exh_99-1.htm, Form of Rights Certificate'}], 'default_option': [{'quote': 'FAILURE TO RETURN THE PROPERLY COMPLETED RIGHTS CERTIFICATE WITH THE CORRECT PAYMENT WILL RESULT IN YOUR NOT BEING ABLE TO EXERCISE YOUR RIGHTS. A Rights holder cannot revoke the exercise of its Rights. Rights not exercised prior to the Expiration Date will expire.', 'location': 'exh_99-2.htm, Form of Letter to Stockholders who are Record Holders'}, {'quote': 'Please note that funds paid by uncertified personal check may take at least five business days to clear. Accordingly, subscription rights holders who wish to pay the purchase price by means of an uncertified personal check are urged to make payment sufficiently in advance of the expiration date to ensure that such payment is received and clears by the expiration date, and are urged to consider payment by means of a certified or bank check, money order or wire transfer of immediately available funds.', 'location': 'exh_99-1.htm, Form of Rights Certificate'}], 'election_deadline': [{'quote': 'The Subscription Rights will expire if they are not exercised by 5:00 p.m., Eastern Time, on February 27, 2026, unless the Company extends the Rights Offering period as described in the Prospectus (such date and time, as it may be extended, the “Expiration Date”).', 'location': 'exh_99-2.htm, Form of Letter to Stockholders who are Record Holders'}, {'quote': 'The Rights Offering is expected to expire at 5:00 p.m., Eastern Time, on February 27, 2026 (“Expiration Date”), subject to extension or earlier termination.', 'location': 'exh_99-6.htm, Press Release Dated February 2, 2026'}, {'quote': 'As indicated in the Prospectus, to exercise your Subscription Rights you should deliver to Securities Transfer Corporation prior to 5:00 p.m., Eastern Time, on the Expiration Date, a properly completed and executed Subscription Certificate with payment of the estimated Subscription Price in full for each share of Common Stock subscribed for pursuant to the Subscription Rights and/or Over-Subscription Rights (if applicable).', 'location': 'exh_99-2.htm, Form of Letter to Stockholders who are Record Holders'}]}
